const stctrlTokenCounts = new Map();
const STCTRL_TOKEN_COUNT_MAX = 64;

// The body is an array of messages, and String(array) is always the same string,
// which collapsed every text of a model onto the first cached count.
function stctrlTokenCountKey(model, body) {
